-- Generated by drizzle-kit, then edited by hand in two places (see
-- docs/decisions.md, 2026-11-09, "Mode changes are teammate events"):
-- the copy into __new_events selects NULL for the new teammate_id column,
-- where drizzle-kit selected a column the old table does not have; and each
-- process profile stored on a teammate row becomes mode_changed events before
-- the column is dropped, so a local database keeps its people's modes.
PRAGMA foreign_keys=OFF;--> statement-breakpoint
CREATE TABLE `__new_events` (
	`seq` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`id` text NOT NULL,
	`card_id` text,
	`teammate_id` text,
	`type` text NOT NULL,
	`actor` text NOT NULL,
	`at` text NOT NULL,
	`at_ms` integer NOT NULL,
	`payload` text NOT NULL,
	FOREIGN KEY (`card_id`) REFERENCES `cards`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`teammate_id`) REFERENCES `teammates`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`actor`) REFERENCES `teammates`(`id`) ON UPDATE no action ON DELETE no action
);
--> statement-breakpoint
INSERT INTO `__new_events`("seq", "id", "card_id", "teammate_id", "type", "actor", "at", "at_ms", "payload") SELECT "seq", "id", "card_id", NULL, "type", "actor", "at", "at_ms", "payload" FROM `events`;--> statement-breakpoint
DROP TABLE `events`;--> statement-breakpoint
ALTER TABLE `__new_events` RENAME TO `events`;--> statement-breakpoint
PRAGMA foreign_keys=ON;--> statement-breakpoint
CREATE UNIQUE INDEX `events_id_unique` ON `events` (`id`);--> statement-breakpoint
CREATE INDEX `events_card_seq` ON `events` (`card_id`,`seq`);--> statement-breakpoint
CREATE INDEX `events_teammate_seq` ON `events` (`teammate_id`,`seq`);--> statement-breakpoint
CREATE INDEX `events_at_ms` ON `events` (`at_ms`);--> statement-breakpoint
INSERT INTO `events`("id", "card_id", "teammate_id", "type", "actor", "at", "at_ms", "payload")
SELECT
	'migrated-mode-' || t.`id` || '-' || p.`key`,
	NULL,
	t.`id`,
	'mode_changed',
	t.`id`,
	strftime('%Y-%m-%dT%H:%M:%fZ', 'now'),
	CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER),
	json_object('function_id', p.`key`, 'from', NULL, 'to', p.`value`)
FROM `teammates` t, json_each(t.`process_profile`) p
WHERE t.`kind` = 'human' AND t.`process_profile` IS NOT NULL
ORDER BY t.`id`, p.`key`;--> statement-breakpoint
ALTER TABLE `teammates` DROP COLUMN `process_profile`;
